import time, random, math
random.seed(0)
def wls_time(n, k, reps=200):
    X=[[random.gauss(0,1) for _ in range(k)]+[1.0] for _ in range(n)]
    y=[random.gauss(0,1) for _ in range(n)]
    t0=time.perf_counter()
    for _ in range(reps):
        A=[[0.0]*k for _ in range(k)]
        for i in range(k):
            for j in range(i,k):
                s=0.0
                for r in range(n): s+=X[r][i]*X[r][j]
                A[i][j]=A[j][i]=s
        b=[0.0]*k
        for i in range(k):
            s=0.0
            for r in range(n): s+=X[r][i]*y[r]
            b[i]=s
        # crude solve
        M=[row[:]+[b[i]] for i,row in enumerate(A)]
        for c in range(k):
            p=max(range(c,k), key=lambda r: abs(M[r][c])); M[c],M[p]=M[p],M[c]
            pv=M[c][c] or 1e-12
            for r in range(k):
                if r!=c and abs(M[r][c])>0:
                    f=M[r][c]/pv
                    for cc in range(c,k+1): M[r][cc]-=f*M[c][cc]
    return (time.perf_counter()-t0)/reps
def spearman_time(n, reps=20):
    x=[random.gauss(0,1) for _ in range(n)]; y=[random.gauss(0,1) for _ in range(n)]
    t0=time.perf_counter()
    for _ in range(reps):
        rx=[v[1] for v in sorted((v,i) for i,v in enumerate(x))]
        ry=[v[1] for v in sorted((v,i) for i,v in enumerate(y))]
        mx=sum(rx)/n; my=sum(ry)/n
        sxx=sum((a-mx)**2 for a in rx); syy=sum((b-my)**2 for b in ry); sxy=sum((a-mx)*(b-my) for a,b in zip(rx,ry))
    return (time.perf_counter()-t0)/reps
